<?php
namespace App\Http\Controllers;
use App\Models\Venue;use Illuminate\Http\Request;use Illuminate\Validation\Rule;use Illuminate\Support\Facades\DB;
class DesignController extends Controller {
 public function show(Request $r,Venue $venue){$this->own($r,$venue);return ['draft'=>array_replace($this->defaults(),$venue->design_draft??$venue->design??[]),'published'=>array_replace($this->defaults(),$venue->design??[])];}
 public function defaults():array{return ['cover_mode'=>'fixed','cover_interval'=>5,'primary'=>'#254d3c','accent'=>'#b86c43','background'=>'#faf8f3','text'=>'#202d26','radius'=>'rounded','font'=>'modern','layout'=>'editorial','modal'=>'center','button'=>'solid','show_reviews'=>true,'welcome'=>'Encuentra tu próxima fecha','cta'=>'Reservar mi fecha','logo_id'=>null,'favicon_id'=>null,'brand_name'=>'','tagline'=>'','font_size'=>'normal','heading_weight'=>'normal','logo_size'=>'medium','hero'=>'split','show_chat'=>true,'show_map'=>true,'page_title'=>''];}
 public function save(Request $r,Venue $venue){$this->own($r,$venue);return DB::transaction(function()use($r,$venue){$venue=Venue::whereKey($venue->id)->lockForUpdate()->firstOrFail();$rules=[];foreach(['primary','accent','background','text'] as $key)$rules[$key]=['required','regex:/^#[0-9a-fA-F]{6}$/'];foreach(['logo','favicon'] as $kind)$rules[$kind.'_id']=['sometimes','nullable','integer',Rule::exists('design_assets','id')->where('venue_id',$venue->id)->where('kind',$kind)];$d=$r->validate($rules+['radius'=>['required',Rule::in(['square','rounded','pill'])],'font'=>['required',Rule::in(['modern','classic','system','humanist','serif','mono'])],'layout'=>['required',Rule::in(['editorial','compact'])],'modal'=>['required',Rule::in(['center','side'])],'button'=>['required',Rule::in(['solid','outline'])],'show_reviews'=>'required|boolean','welcome'=>'required|string|max:120','cta'=>'required|string|max:60','publish'=>'sometimes|boolean','brand_name'=>'sometimes|nullable|string|max:80','tagline'=>'sometimes|nullable|string|max:160','page_title'=>'sometimes|nullable|string|max:80','font_size'=>['sometimes',Rule::in(['normal','large'])],'heading_weight'=>['sometimes',Rule::in(['normal','bold'])],'logo_size'=>['sometimes',Rule::in(['small','medium','large'])],'hero'=>['sometimes',Rule::in(['split','stacked'])],'cover_mode'=>['sometimes',Rule::in(['fixed','carousel'])],'cover_interval'=>'sometimes|integer|between:3,20','show_chat'=>'sometimes|boolean','show_map'=>'sometimes|boolean']);$publish=$d['publish']??false;unset($d['publish']);$d=array_replace($this->defaults(),$d);$venue->design_draft=$d;if($publish)$venue->design=$d;$venue->save();return ['draft'=>$d,'published'=>$venue->design??$this->defaults()];});}
 private function own(Request $r,Venue $v){abort_unless($v->owner_account_id===$r->user()->id,403);}
}
